import {
    Table,
    BooleanColumn,
    UserRolesColumn,
    GenericColumn,
    ChoiceColumn,
    GuidColumn,
    ScriptColumn,
    TableNameColumn,
    ConditionsColumn,
    ReferenceColumn,
} from '../../db'

export const sysrule_view_workspace = Table({
    actions: {
        read: true,
        update: false,
        delete: false,
        create: false,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        no_labels: true,
        update_synch: true,
    },
    extends: 'sysrule',
    label: 'View Rule',
    name: 'sysrule_view_workspace',
    schema: {
        hide_journal_input_fields: BooleanColumn({
            maxLength: 40,
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                record_watcher_blacklist: true,
            },
            maxLength: 100,
        }),
        tabs_order: GenericColumn({
            columnType: 'order_list',
            label: [
                {
                    label: 'Tab Order',
                    hint: 'Order Related lists and Related Items, configured for current table, view and workspace',
                },
            ],
            maxLength: 4000,
        }),
        default_tab_focus: ChoiceColumn({
            default: 'Details',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Select Item to have default focus',
                },
            ],
            maxLength: 40,
        }),
        hide_details: BooleanColumn({
            label: 'Hide details & UI actions',
            maxLength: 40,
        }),
        sys_id: GuidColumn({
            maxLength: 32,
            primary: true,
        }),
        active: BooleanColumn({
            default: true,
            maxLength: 40,
        }),
        script: ScriptColumn({
            maxLength: 8000,
        }),
        advanced: BooleanColumn({
            maxLength: 40,
        }),
        default_tab_order: BooleanColumn({
            default: true,
            maxLength: 40,
        }),
        hide_section_menu: BooleanColumn({
            label: 'Hide section navigation',
            maxLength: 40,
        }),
        table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
            },
            mandatory: true,
            maxLength: 80,
        }),
        condition: ConditionsColumn({
            dependent: 'table',
            label: 'Conditions',
            maxLength: 1000,
        }),
        view: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            mandatory: true,
            maxLength: 32,
            referenceTable: 'sys_ui_view',
            referenceQual: "javascript:current.addQuery('sys_id', getAllTableViews(current.table));",
        }),
        experience_restricted: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Make this view rule restricted to experiences',
                },
            ],
            maxLength: 40,
        }),
        disable_section_collapse: BooleanColumn({
            label: [
                {
                    label: 'Disable section collapsing',
                    hint: 'Remove ability to collapse sections in workspace',
                },
            ],
            maxLength: 40,
        }),
        workspace: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            maxLength: 32,
            referenceTable: 'sys_aw_master_config',
        }),
    },
    textIndex: true,
})
